import Foundation

enum WebDashboard {
    static let html = #"""
<!doctype html>
<html lang="ja">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>MCS Manager</title>
<style>
:root{color-scheme:dark;--bg:#05070b;--header:#080d15;--panel:#0d141f;--card:#111c2b;--line:#29415f;--text:#f7faff;--muted:#aebbd0;--blue:#59a6ff;--green:#42d99a;--yellow:#ffd166;--red:#ff7185}
*{box-sizing:border-box}html,body{min-height:100%}body{margin:0;background:var(--bg);color:var(--text);font:14px -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}button,input{font:inherit}button{cursor:pointer;min-height:44px}.top{height:58px;display:flex;align-items:center;padding:0 20px;border-bottom:1px solid var(--line);background:var(--header);position:sticky;top:0;z-index:5}.brand{font-size:17px;font-weight:760;color:#fff}.grow{flex:1}.muted{color:var(--muted)}.layout{display:grid;grid-template-columns:260px minmax(0,1fr);min-height:calc(100vh - 58px)}aside,main{min-width:0}aside{padding:14px;border-right:1px solid var(--line);background:var(--header)}.server{width:100%;padding:11px;margin:0 0 7px;border:1px solid var(--line);border-radius:10px;background:#0a111c;color:var(--text);text-align:left;overflow-wrap:anywhere}.server:hover{background:#14243a;border-color:#3f6d9e}.server.active{background:#142a45;border-color:var(--blue);box-shadow:inset 3px 0 0 var(--blue)}.dot{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:8px;background:var(--muted)}.dot.running{background:var(--green)}.dot.starting,.dot.stopping{background:var(--yellow)}.dot.orphaned{background:var(--red)}main{padding:22px;max-width:1100px;width:100%;margin:auto}.title{display:flex;align-items:flex-start;gap:10px;margin-bottom:16px;flex-wrap:wrap}.title h1{font-size:22px;margin:7px 0;flex:1 1 280px;min-width:0;overflow-wrap:anywhere}.status-label{margin-top:12px}.actions{display:flex;gap:8px;flex-wrap:wrap;margin-left:auto}.btn{border:1px solid #426084;border-radius:8px;padding:8px 12px;background:#122136;color:#f7faff}.btn:hover{background:#19304d;border-color:#6798cf}.btn:focus-visible,input:focus-visible{outline:2px solid var(--blue);outline-offset:2px}.btn:disabled{cursor:default;opacity:.42}.primary{background:#123967;border-color:#4c98e8;color:#fff}.danger{background:#3b1720;border-color:#ad4c5d;color:#ffc2ca}.success{background:#103a2a;border-color:#318661;color:#baffdc}.tabs{display:flex;gap:4px;border-bottom:1px solid var(--line);margin-bottom:16px;overflow-x:auto}.tab{border:0;background:transparent;color:var(--muted);padding:10px 13px;border-bottom:3px solid transparent;white-space:nowrap}.tab.active{color:#fff;background:#10233a;border-color:var(--blue)}.grid{display:grid;grid-template-columns:repeat(4,minmax(120px,1fr));gap:10px}.card{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:14px;box-shadow:0 8px 24px #0004}.metric strong{display:block;font-size:22px;margin-top:7px;color:#fff}.warn{color:var(--yellow)}.bad{color:var(--red)}.good{color:var(--green)}.section{margin-top:12px}.row{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.field{display:grid;grid-template-columns:180px minmax(0,1fr);align-items:center;gap:12px;margin:10px 0}.field input,.text-input{width:100%;min-height:44px;padding:9px;border:1px solid #395777;border-radius:8px;background:#030509;color:var(--text)}input[type=checkbox]{accent-color:var(--blue)}.pill{display:inline-flex;align-items:center;gap:5px;border:1px solid #365575;background:#101d2d;border-radius:999px;padding:3px 3px 3px 10px;margin:3px}.icon-btn{width:44px;height:44px;padding:0;border-radius:50%}.console{width:100%;height:300px;overflow:auto;white-space:pre-wrap;background:#020305;border:1px solid #29415f;border-radius:9px;padding:10px;font:12px ui-monospace,monospace;color:#dcecff}.flash{display:none;margin-bottom:12px;padding:10px;border:1px solid var(--line);border-radius:8px;background:#10243d}.empty,.loading{text-align:center;padding:60px 15px;color:var(--muted)}#login{max-width:360px;margin:15vh auto;padding:24px}#login input{width:100%;min-height:44px;padding:11px;margin:12px 0;border-radius:8px;border:1px solid #426084;background:#020305;color:var(--text)}.modal-backdrop{position:fixed;inset:0;background:#000c;display:flex;align-items:center;justify-content:center;padding:20px;z-index:20}.modal{max-width:430px;width:100%;background:var(--panel);border:1px solid #486b91;border-radius:14px;padding:18px}.modal-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:18px}
@media(max-width:760px){.layout{grid-template-columns:1fr}aside{border-right:0;border-bottom:1px solid var(--line);display:flex;overflow:auto}.server{min-width:180px;margin-right:6px}.grid{grid-template-columns:repeat(2,minmax(0,1fr))}main{padding:14px}.field{grid-template-columns:1fr;gap:4px}.title h1{flex-basis:100%;margin-bottom:0}.status-label{margin-top:0}.actions{width:100%;margin:4px 0 0}.actions .btn{flex:1 1 120px;white-space:normal}.tabs .tab{flex:1 0 auto;min-width:88px}}
@media(max-width:390px){.grid{grid-template-columns:1fr}.top{padding:0 14px}.metric strong{font-size:20px}}
</style>
</head>
<body>
<div id="login" class="card"><h2>MCS Manager</h2><div class="muted" data-i="loginHelp">管理パスワードを入力してください</div><input id="password" type="password" autocomplete="current-password"><button class="btn primary" onclick="login(true)" data-i="login">ログイン</button><div id="loginError" class="bad" style="margin-top:10px"></div></div>
<div id="app" style="display:none"><header class="top"><span class="brand">◆ MCS Manager</span><span class="grow"></span><span class="muted" style="margin-right:10px">v1.0.0</span><button class="btn" onclick="toggleLanguage()" id="lang">English</button></header><div class="layout"><aside id="servers"></aside><main><div id="flash" class="flash" role="status"></div><div id="content"></div></main></div></div><div id="modalRoot"></div>
<script>
let token=sessionStorage.getItem('mcs-token')||'',selected='',currentTab='status',state={servers:[]},lang=localStorage.getItem('mcs-lang')||'ja',refreshInFlight=false,actionInFlight=false;
const tr={
ja:{login:'ログイン',loginHelp:'管理パスワードを入力してください',authFailed:'認証に失敗しました',status:'ステータス',settings:'設定',users:'ホワイトリスト',console:'コンソール',start:'起動',stop:'停止',restart:'再起動',kill:'強制終了',remove:'一覧から削除',players:'参加人数',memory:'メモリ使用量',cpu:'サーバー負荷',latency:'接続遅延',tps:'TPS',mspt:'MSPT',lag:'ラグ',leak:'継続的なメモリ増加',healthy:'正常',uptime:'稼働時間',version:'バージョン',save:'設定を保存',saved:'設定を保存しました',wl:'ホワイトリスト',enabled:'有効',add:'追加',send:'送信',sent:'送信しました',reload:'更新',loading:'読み込み中…',noServers:'登録済みサーバーがありません',confirmDelete:'このサーバーを一覧から削除しますか？ サーバーファイルは削除されません。',cancel:'キャンセル',stopped:'停止中',running:'稼働中',starting:'起動処理中',stopping:'停止処理中',orphaned:'外部プロセスを検出',stopToEdit:'設定を変更するにはサーバーを停止してください',motd:'サーバー説明（MOTD）',maxPlayers:'最大参加人数',port:'サーバーポート',viewDistance:'描画距離',simulationDistance:'シミュレーション距離',onlineMode:'オンライン認証',playerName:'プレイヤー名',command:'コマンドを入力',removePlayer:'削除'},
en:{login:'Login',loginHelp:'Enter the management password',authFailed:'Authentication failed',status:'Status',settings:'Settings',users:'Whitelist',console:'Console',start:'Start',stop:'Stop',restart:'Restart',kill:'Force stop',remove:'Remove from list',players:'Players',memory:'Memory usage',cpu:'Server load',latency:'Connection latency',tps:'TPS',mspt:'MSPT',lag:'Lag',leak:'Sustained memory growth',healthy:'Healthy',uptime:'Uptime',version:'Version',save:'Save settings',saved:'Settings saved',wl:'Whitelist',enabled:'Enabled',add:'Add',send:'Send',sent:'Sent',reload:'Refresh',loading:'Loading…',noServers:'No registered servers',confirmDelete:'Remove this server from the list? Server files will not be deleted.',cancel:'Cancel',stopped:'Stopped',running:'Running',starting:'Starting',stopping:'Stopping',orphaned:'Detached process detected',stopToEdit:'Stop the server before editing settings',motd:'Server description (MOTD)',maxPlayers:'Maximum players',port:'Server port',viewDistance:'View distance',simulationDistance:'Simulation distance',onlineMode:'Online authentication',playerName:'Player name',command:'Enter a command',removePlayer:'Remove'}
};
const t=k=>tr[lang][k]||k,esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(method,path,body){let h={'Content-Type':'application/json'};if(token)h.Authorization='Bearer '+token;try{let r=await fetch(path,{method,headers:h,body:body===undefined?undefined:JSON.stringify(body)}),d=await r.json();if(r.status===401){showLogin();return null}if(!r.ok)throw Error(d.error||r.statusText);return d}catch(e){flash(e.message,true);return null}}
function showLogin(){document.querySelector('#app').style.display='none';document.querySelector('#login').style.display='block'}
async function login(fromForm){if(fromForm){token=document.querySelector('#password').value;sessionStorage.setItem('mcs-token',token)}let d=await api('GET','/api/status');if(d){document.querySelector('#login').style.display='none';document.querySelector('#app').style.display='block';document.querySelector('#loginError').textContent='';applyLanguage();await refresh(d)}else document.querySelector('#loginError').textContent=t('authFailed')}
function applyLanguage(){document.documentElement.lang=lang;document.querySelector('#lang').textContent=lang==='ja'?'English':'日本語';document.querySelectorAll('[data-i]').forEach(e=>e.textContent=t(e.dataset.i))}
function toggleLanguage(){lang=lang==='ja'?'en':'ja';localStorage.setItem('mcs-lang',lang);applyLanguage();render()}
function flash(msg,isBad){let e=document.querySelector('#flash');e.textContent=msg;e.style.display='block';e.style.color=isBad?'var(--red)':'var(--green)';clearTimeout(e.timer);e.timer=setTimeout(()=>e.style.display='none',3500)}
async function refresh(prefetched){if(refreshInFlight&&!prefetched)return;refreshInFlight=true;try{let d=prefetched||await api('GET','/api/status');if(!d)return;state=d;let ids=d.servers.map(s=>s.id);if(!selected||!ids.includes(selected))selected=ids[0]||'';render()}finally{refreshInFlight=false}}
function controls(s){if(s.status==='stopped')return `<button class="btn success" onclick="act('start')">▶ ${t('start')}</button>`;if(s.status==='orphaned')return `<button class="btn danger" onclick="act('kill')">■ ${t('kill')}</button>`;if(s.status==='running'||s.status==='starting')return `<button class="btn" onclick="act('stop')">■ ${t('stop')}</button><button class="btn" onclick="act('restart')">↻ ${t('restart')}</button>`;return ''}
function render(){let list=document.querySelector('#servers');list.innerHTML=(state.servers||[]).map(s=>`<button class="server ${s.id===selected?'active':''}" onclick="selectServer('${s.id}')"><span class="dot ${s.status}"></span><b>${esc(s.name)}</b><br><small class="muted">${t(s.status)} · ${s.playerCount}/${s.maxPlayers}</small></button>`).join('');let s=(state.servers||[]).find(x=>x.id===selected);if(!s){document.querySelector('#content').innerHTML=`<div class="empty">${t('noServers')}</div>`;return}let remove=s.status==='stopped'?`<button class="btn danger" onclick="openDeleteDialog()">${t('remove')}</button>`:'';document.querySelector('#content').innerHTML=`<div class="title"><h1>${esc(s.name)}</h1><span class="muted status-label">${t(s.status)}</span><div class="actions">${controls(s)}${remove}</div></div><nav class="tabs">${['status','settings','users','console'].map(x=>`<button class="tab ${x===currentTab?'active':''}" data-tab="${x}" onclick="tab('${x}')">${t(x)}</button>`).join('')}</nav><div id="panel"></div>`;renderPanel(s)}
function renderPanel(s){let p=document.querySelector('#panel');if(currentTab==='status'){let leak=s.memoryLeakWarning?`<span class="bad">⚠ ${t('leak')}</span>`:`<span class="good">✓ ${t('healthy')}</span>`;p.innerHTML=`<div class="grid"><div class="card metric"><span class="muted">${t('memory')}</span><strong>${num(s.memoryMB,0)} MB</strong>${leak}</div><div class="card metric"><span class="muted">${t('cpu')}</span><strong>${num(s.cpuPercent,1)}%</strong></div><div class="card metric"><span class="muted">${t('players')}</span><strong>${s.playerCount}/${s.maxPlayers}</strong></div><div class="card metric"><span class="muted">${t('latency')}</span><strong>${s.latencyMS==null?'—':num(s.latencyMS,1)+' ms'}</strong></div><div class="card metric"><span class="muted">${t('tps')}</span><strong>${s.tps==null?'—':num(s.tps,1)}</strong></div><div class="card metric"><span class="muted">${t('mspt')}</span><strong>${s.mspt==null?'—':num(s.mspt,1)}</strong></div><div class="card metric"><span class="muted">${t('lag')}</span><strong>${num(s.lagMS,0)} ms</strong></div><div class="card metric"><span class="muted">${t('uptime')}</span><strong>${duration(s.uptime)}</strong></div></div><div class="card section"><b>${t('version')}</b><div class="muted" style="margin-top:6px">Minecraft ${esc(s.version)} · ${esc(s.jar)}</div></div>`;return}p.innerHTML=`<div class="loading">${t('loading')}</div>`;if(currentTab==='settings')loadSettings();else if(currentTab==='users')loadWhitelist();else loadLogs()}
function selectServer(id){selected=id;currentTab='status';render()}
function tab(x){if(currentTab===x)return;currentTab=x;document.querySelectorAll('.tab').forEach(e=>e.classList.toggle('active',e.dataset.tab===x));let s=(state.servers||[]).find(v=>v.id===selected);if(s)renderPanel(s)}
async function act(a){if(actionInFlight)return;actionInFlight=true;try{let d=await api('POST',`/api/servers/${selected}/${a}`);if(d){flash('OK');setTimeout(()=>refresh(),800)}}finally{actionInFlight=false}}
function openDeleteDialog(){document.querySelector('#modalRoot').innerHTML=`<div class="modal-backdrop" role="presentation"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="deleteTitle"><b id="deleteTitle">${t('remove')}</b><p>${t('confirmDelete')}</p><div class="modal-actions"><button class="btn" onclick="closeDeleteDialog()">${t('cancel')}</button><button class="btn danger" onclick="confirmRemoveServer()">${t('remove')}</button></div></div></div>`}
function closeDeleteDialog(){document.querySelector('#modalRoot').innerHTML=''}
async function confirmRemoveServer(){if(actionInFlight)return;actionInFlight=true;try{let d=await api('DELETE',`/api/servers/${selected}`);if(d){selected='';closeDeleteDialog();await refresh()}}finally{actionInFlight=false}}
async function loadSettings(){let id=selected,d=await api('GET',`/api/servers/${id}/settings`);if(!d||currentTab!=='settings'||selected!==id)return;let s=d.settings,disabled=(state.servers.find(x=>x.id===id)?.status!=='stopped');document.querySelector('#panel').innerHTML=`<div class="card">${disabled?`<p class="warn">${t('stopToEdit')}</p>`:''}<label class="field"><span>${t('motd')}</span><input id="motd" value="${esc(s.motd)}" ${disabled?'disabled':''}></label><label class="field"><span>${t('maxPlayers')}</span><input id="maxPlayers" type="number" min="1" max="10000" value="${s.maxPlayers}" ${disabled?'disabled':''}></label><label class="field"><span>${t('port')}</span><input id="serverPort" type="number" min="1" max="65535" value="${s.serverPort}" ${disabled?'disabled':''}></label><label class="field"><span>${t('viewDistance')}</span><input id="viewDistance" type="number" min="2" max="32" value="${s.viewDistance}" ${disabled?'disabled':''}></label><label class="field"><span>${t('simulationDistance')}</span><input id="simulationDistance" type="number" min="2" max="32" value="${s.simulationDistance}" ${disabled?'disabled':''}></label><label class="field"><span>${t('onlineMode')}</span><input id="onlineMode" type="checkbox" ${s.onlineMode?'checked':''} ${disabled?'disabled':''}></label><button class="btn primary" onclick="saveSettings()" ${disabled?'disabled':''}>${t('save')}</button></div>`}
async function saveSettings(){let v=id=>document.querySelector('#'+id),body={motd:v('motd').value,maxPlayers:+v('maxPlayers').value,serverPort:+v('serverPort').value,viewDistance:+v('viewDistance').value,simulationDistance:+v('simulationDistance').value,onlineMode:v('onlineMode').checked};if(await api('POST',`/api/servers/${selected}/settings`,body))flash(t('saved'))}
async function loadWhitelist(){let id=selected,d=await api('GET',`/api/servers/${id}/whitelist`);if(!d||currentTab!=='users'||selected!==id)return;let s=state.servers.find(x=>x.id===id);document.querySelector('#panel').innerHTML=`<div class="card"><div class="row"><b>${t('wl')}</b><span class="grow"></span><label><input type="checkbox" ${s.whitelistEnabled?'checked':''} onchange="toggleWL(this.checked)"> ${t('enabled')}</label></div><div class="row section"><input class="text-input" id="wlName" maxlength="32" placeholder="${t('playerName')}" style="flex:1"><button class="btn primary" onclick="addWL()">${t('add')}</button></div><div class="section">${(d.whitelist||[]).map(x=>`<span class="pill">${esc(x.name)}${x.pending?' ⏳':''}${x.uuid?`<button class="btn danger icon-btn" aria-label="${t('removePlayer')} ${esc(x.name)}" onclick="delWL('${encodeURIComponent(x.uuid)}')">×</button>`:''}</span>`).join('')}</div></div>`}
async function toggleWL(enabled){if(await api('POST',`/api/servers/${selected}/whitelist-enabled`,{enabled}))await refresh()}
async function addWL(){let n=document.querySelector('#wlName').value.trim();if(n&&await api('POST',`/api/servers/${selected}/whitelist`,{name:n}))loadWhitelist()}
async function delWL(id){if(await api('DELETE',`/api/servers/${selected}/whitelist/${id}`))loadWhitelist()}
async function loadLogs(){let id=selected,d=await api('GET',`/api/servers/${id}/logs`);if(!d||currentTab!=='console'||selected!==id)return;document.querySelector('#panel').innerHTML=`<div class="row" style="justify-content:flex-end"><button class="btn" onclick="loadLogs()">${t('reload')}</button></div><pre class="console">${esc((d.logs||[]).slice(-200).map(x=>`${x.time||''} ${x.level||''} ${x.message}`).join('\n'))}</pre><div class="row section"><input class="text-input" id="command" style="flex:1" placeholder="${t('command')}"><button class="btn primary" onclick="sendCommand()">${t('send')}</button></div>`}
async function sendCommand(){let e=document.querySelector('#command'),c=e.value.trim();if(c&&await api('POST',`/api/servers/${selected}/command`,{command:c})){e.value='';flash(t('sent'))}}
function num(v,d){return Number(v||0).toFixed(d)}function duration(v){v=Number(v||0);return `${Math.floor(v/3600)}:${String(Math.floor(v%3600/60)).padStart(2,'0')}:${String(Math.floor(v%60)).padStart(2,'0')}`}
document.querySelector('#password').addEventListener('keydown',e=>{if(e.key==='Enter')login(true)});applyLanguage();if(token)login(false);setInterval(()=>{if(document.querySelector('#app').style.display!=='none'&&currentTab==='status')refresh()},5000);
</script>
</body>
</html>
"""#
}
